UPDATE ifj_concurrency_permit permit
JOIN ifj_trigger_work_item work_item
  ON work_item.trigger_id = permit.owner_trigger_id
SET permit.lease_deadline = TIMESTAMPADD(MICROSECOND, #{leaseMicros}, CURRENT_TIMESTAMP(3)),
    permit.update_time = CURRENT_TIMESTAMP(3)
WHERE permit.permit_token = #{permitToken}
  AND permit.lease_owner = #{leaseOwner}
  AND permit.permit_fence = #{permitFence}
  AND permit.execution_fence = #{executionFence}
  AND permit.lease_deadline > CURRENT_TIMESTAMP(3)
  AND work_item.status = 'CLAIMED'
  AND work_item.fence_token = #{executionFence}
  AND work_item.lease_deadline > CURRENT_TIMESTAMP(3)

UPDATE ifj_concurrency_permit
SET owner_instance_id = NULL,
    owner_root_instance_id = NULL,
    owner_trigger_id = NULL,
    lease_owner = NULL,
    permit_token = NULL,
    execution_fence = NULL,
    lease_deadline = NULL,
    update_time = CURRENT_TIMESTAMP(3)
WHERE permit_token = #{permitToken}
  AND lease_owner = #{leaseOwner}
  AND permit_fence = #{permitFence}
  AND execution_fence = #{executionFence}

UPDATE ifj_concurrency_permit
SET owner_instance_id = NULL,
    owner_root_instance_id = NULL,
    owner_trigger_id = NULL,
    lease_owner = NULL,
    permit_token = NULL,
    execution_fence = NULL,
    lease_deadline = NULL,
    update_time = strftime('%Y-%m-%d %H:%M:%f','now')
WHERE permit_token = #{permitToken}
  AND lease_owner = #{leaseOwner}
  AND permit_fence = #{permitFence}
  AND execution_fence = #{executionFence}

UPDATE ifj_concurrency_permit
SET owner_instance_id = NULL,
    owner_root_instance_id = NULL,
    owner_trigger_id = NULL,
    lease_owner = NULL,
    permit_token = NULL,
    execution_fence = NULL,
    lease_deadline = NULL,
    update_time = CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3))
WHERE permit_token = #{permitToken}
  AND lease_owner = #{leaseOwner}
  AND permit_fence = #{permitFence}
  AND execution_fence = #{executionFence}

UPDATE ifj_concurrency_permit
SET owner_instance_id = NULL,
    owner_root_instance_id = NULL,
    owner_trigger_id = NULL,
