SELECT CASE WHEN COUNT(*) = 1 THEN TRUE ELSE FALSE END
FROM ifj_instance instance_record
JOIN ifj_trigger_work_item work_item
  ON work_item.trigger_id = instance_record.trigger_id
WHERE instance_record.id = #{instanceId}
  AND instance_record.execution_fence = #{executionFence}
  AND instance_record.status IN ('WAITING', 'RUNNING')
  AND work_item.status = 'CLAIMED'
  AND work_item.claim_token = #{claimToken}
  AND work_item.fence_token = #{executionFence}
  AND work_item.lease_deadline > CURRENT_TIMESTAMP(3)

