mapper.update:
UPDATE ifj_concurrency_permit permit
SET lease_deadline = (CURRENT_TIMESTAMP(3) + (#{leaseMicros} * INTERVAL '1 microsecond')),
    update_time = CURRENT_TIMESTAMP(3)
FROM ifj_trigger_work_item work_item
WHERE work_item.trigger_id = permit.owner_trigger_id
  AND permit.permit_token = #{permitToken}
  AND permit.lease_owner = #{leaseOwner}
  AND permit.permit_fence = #{permitFence}
  AND permit.execution_fence = #{executionFence}
  AND permit.lease_deadline > CURRENT_TIMESTAMP(3)
  AND work_item.status = 'CLAIMED'
  AND work_item.fence_token = #{executionFence}
  AND work_item.lease_deadline > CURRENT_TIMESTAMP(3)

UPDATE ifj_concurrency_permit AS permit
SET lease_deadline = strftime('%Y-%m-%d %H:%M:%f','now', printf('+%.6f seconds', (#{leaseMicros} / 1000000.0))),
    update_time = strftime('%Y-%m-%d %H:%M:%f','now')
FROM ifj_trigger_work_item work_item
WHERE work_item.trigger_id = permit.owner_trigger_id
  AND permit.permit_token = #{permitToken}
  AND permit.lease_owner = #{leaseOwner}
  AND permit.permit_fence = #{permitFence}
  AND permit.execution_fence = #{executionFence}
  AND permit.lease_deadline > strftime('%Y-%m-%d %H:%M:%f','now')
  AND work_item.status = 'CLAIMED'
  AND work_item.fence_token = #{executionFence}
  AND work_item.lease_deadline > strftime('%Y-%m-%d %H:%M:%f','now')

MERGE INTO ifj_concurrency_permit permit
USING (
    SELECT permit.ROWID AS target_rowid
    FROM ifj_concurrency_permit permit, ifj_trigger_work_item work_item
    WHERE work_item.trigger_id = permit.owner_trigger_id
  AND permit.permit_token = #{permitToken}
  AND permit.lease_owner = #{leaseOwner}
  AND permit.permit_fence = #{permitFence}
  AND permit.execution_fence = #{executionFence}
  AND permit.lease_deadline > CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3))
  AND work_item.status = 'CLAIMED'
  AND work_item.fence_token = #{executionFence}
  AND work_item.lease_deadline > CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3))
) source
ON (permit.ROWID = source.target_rowid)
WHEN MATCHED THEN UPDATE SET lease_deadline = CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3)) + NUMTODSINTERVAL(#{leaseMicros} / 1000000, 'SECOND'),
    update_time = CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3))

UPDATE permit
SET lease_deadline = DATEADD(MILLISECOND, (#{leaseMicros} / 1000), SYSUTCDATETIME()),
    update_time = SYSUTCDATETIME()
FROM ifj_concurrency_permit AS permit,
     ifj_trigger_work_item work_item
WHERE work_item.trigger_id = permit.owner_trigger_id
  AND permit.permit_token = #{permitToken}
  AND permit.lease_owner = #{leaseOwner}
  AND permit.permit_fence = #{permitFence}
  AND permit.execution_fence = #{executionFence}
  AND permit.lease_deadline > SYSUTCDATETIME()
  AND work_item.status = 'CLAIMED'
  AND work_item.fence_token = #{executionFence}
  AND work_item.lease_deadline > SYSUTCDATETIME()
